package com.householdfinance.finance.application;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import com.householdfinance.finance.application.port.in.*;import com.householdfinance.finance.application.port.out.*;import com.householdfinance.finance.application.service.ServiceFactory;import com.householdfinance.finance.domain.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.mockito.*;
class FinanceApplicationTest{@Mock FinanceRepository repository;@BeforeEach void setup(){MockitoAnnotations.openMocks(this);when(repository.save(any(Household.class))).thenAnswer(i->i.getArgument(0));when(repository.save(any(FinancialAccount.class))).thenAnswer(i->i.getArgument(0));} @Test void createThenRequireActiveMembership(){var owner=UUID.randomUUID();var h=Household.create("home",owner,Instant.now());when(repository.household(h.id())).thenReturn(Optional.of(h));HouseholdUseCase use=ServiceFactory.household(repository);assertThat(use.get(owner,h.id())).isSameAs(h);assertThatThrownBy(()->use.get(UUID.randomUUID(),h.id())).isInstanceOf(DomainException.class);}@Test void accountOpeningRequiresMembership(){var owner=UUID.randomUUID();var h=Household.create("home",owner,Instant.now());when(repository.household(h.id())).thenReturn(Optional.of(h));AccountUseCase use=ServiceFactory.account(repository);var account=use.open(owner,h.id(),"cash",AccountType.CASH,Money.of(new java.math.BigDecimal("10"),"USD"));assertThat(account.balance().amount()).isEqualByComparingTo("10");}}
